Switched to a new branch 'feat/story-evals'
import { createStep, createWorkflow } from '@mastra/core/workflows';
import { z } from 'zod';
import { epitaph } from '#lib/epitaph.ts';
import { VOICES } from '#lib/types.ts';
import type { Candidate, Inscription, Story } from '#lib/types.ts';
import { runFailure } from './http.ts';
import { inference } from './inference/gemma.ts';
import { groundParagraph, groundStone, hasEvidence, verifyFacts } from './narrative.ts';
import { fetchPage } from './pages.ts';
import { candidateSchema, inscriptionSchema, sourceSchema } from './research.ts';
import { narratorVoice } from './voice.ts';

const MAX_PAGES = 5;
const MAX_CHARS = 12_000;

export const candidateInputSchema = candidateSchema.extend({
	sources: z.array(sourceSchema).min(1).max(MAX_PAGES)
});

const inputSchema = z.object({ inscription: inscriptionSchema, candidate: candidateInputSchema });
const pageSchema = z.object({ sourceId: z.string(), text: z.string() });
const withPages = inputSchema.extend({ pages: z.array(pageSchema) });
const factSchema = z.object({
	claim: z.enum(['name', 'birth', 'death', 'other']),
	sourceId: z.string(),
	quote: z.string()
});
const withFacts = withPages.extend({ facts: z.array(factSchema) });
const withParagraph = withFacts.extend({ paragraph: z.string() });
const storySchema = z.discriminatedUnion('status', [
	z.object({
		status: z.literal('told'),
		paragraph: z.string(),
		sources: z.array(sourceSchema),
		voice: z.enum(VOICES)
	}),
	z.object({ status: z.literal('insufficient') })
]);

const fetchStep = createStep({
	id: 'fetch',
	inputSchema,
	outputSchema: withPages,
	execute: async ({ inputData }) => ({
		...inputData,
		pages: await Promise.all(
			inputData.candidate.sources.slice(0, MAX_PAGES).map(async (s) => ({
				sourceId: s.id,
				text: ((await fetchPage(s.url)) ?? s.snippet).slice(0, MAX_CHARS)
			}))
		)
	})
});

const extractStep = createStep({
	id: 'extract',
	inputSchema: withPages,
	outputSchema: withFacts,
	execute: async ({ inputData }) => ({
		...inputData,
		facts: verifyFacts(
			inputData.candidate,
			inputData.pages,
			await inference.extractFacts(inputData.inscription, inputData.candidate, inputData.pages)
		)
	})
});

const tellStep = createStep({
	id: 'tell',
	inputSchema: withFacts,
	outputSchema: withParagraph,
	execute: async ({ inputData }) => ({
		...inputData,
		// With nothing beyond the name and dates there is no story to tell, so skip the model.
		paragraph: hasEvidence(inputData.inscription, inputData.candidate, inputData.facts)
			? await inference.tellStory(
					inputData.candidate.name,
					inputData.facts.map((f) => f.quote)
				)
			: ''
	})
});

const groundStep = createStep({
	id: 'ground',
	inputSchema: withParagraph,
	outputSchema: storySchema,
	execute: ({ inputData }) => {
		const { inscription, candidate, facts, paragraph } = inputData;
		const grounded = groundParagraph(inscription, candidate, facts, paragraph);
		return Promise.resolve(
			grounded.status === 'told'
				? {
						...grounded,
						voice: narratorVoice(
							inscription,
							facts.map((f) => f.quote)
						)
					}
				: grounded
		);
	}
});

const storyWorkflow = createWorkflow({ id: 'story', inputSchema, outputSchema: storySchema })
	.then(fetchStep)
	.then(extractStep)
	.then(tellStep)
	.then(groundStep)
	.commit();

/**
 * Writes a paragraph around what the stone says and grounds it against the stone alone.
 * @param inscription The stone's person.
 * @param today Current date, for how long they have been buried.
 * @returns A stone story.
 * @throws {ProviderError} When the model fails after retries.
 */
export async function runStoneStory(inscription: Inscription, today = new Date()): Promise<Story> {
	const facts = epitaph(inscription, today);
	const paragraph = await inference.tellStory(inscription.name, facts);
	return {
		status: 'stone',
		paragraph: groundStone(inscription, facts, paragraph),
		voice: narratorVoice(inscription, [])
	};
}

/**
 * Fetches the candidate's sources, extracts verified facts, writes a paragraph around them and
 * grounds it against those facts. Falls back to the stone when the records add nothing.
 * @param inscription The stone's person.
 * @param candidate The candidate the visitor confirmed.
 * @returns A grounded story.
 * @throws {ProviderError} When the model fails after retries.
 */
export async function runStory(inscription: Inscription, candidate: Candidate): Promise<Story> {
	const run = await storyWorkflow.createRun();
	const result = await run.start({ inputData: { inscription, candidate } });
	if (result.status !== 'success') {
		throw runFailure('Story', result.status === 'failed' ? result.error : undefined);
	}
	return result.result.status === 'told' ? result.result : runStoneStory(inscription);
}
import type { Candidate, Inscription, Story } from '#lib/types.ts';
import type { PageText, RawFact } from './inference/index.ts';

const MONTHS = new Set(
	(
		'january february march april may june july august september october november december ' +
		'jan feb mar apr jun jul aug sep sept oct nov dec'
	).split(' ')
);

// Spelled-out numbers compare equal to their digits, so "forty" and "40" support each other.
// "one" is left out: "no one" and "one more time" are ordinary prose, not a count.
// A Map, not an object: a prose word such as "constructor" must not hit an inherited property.
const NUMBER_VALUES = new Map<string, string>([
	...'two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty'
		.split(' ')
		.map((w, i): [string, string] => [w, String(i + 2)]),
	['thirty', '30'],
	['forty', '40'],
	['fifty', '50'],
	['sixty', '60'],
	['seventy', '70'],
	['eighty', '80'],
	['ninety', '90'],
	['hundred', '100'],
	['thousand', '1000']
]);

// "twenty-four" is one number, so it must equal "24" as a whole; token by token it would not.
const TENS = 'twenty thirty forty fifty sixty seventy eighty ninety'.split(' ');
const ONES = 'one two three four five six seven eight nine'.split(' ');
const COMPOUND_NUMBER = new RegExp(
	String.raw`\b(${TENS.join('|')})[\s-](${ONES.join('|')})\b`,
	'giu'
);

// Negations flip a claim, so one that touches a fact must come from that fact.
const NEGATIONS = new Set('not never no none nobody neither nor without cannot'.split(' '));

// Words this short are filler; only longer words identify what a sentence is about.
const MIN_TOPIC_LENGTH = 5;
// Compare word stems so "preceded"/"preceding" match without a stemmer dependency.
const STEM_LENGTH = 5;
// A fact counts as used when at least this share of its topic words appear in the story.
const MIN_FACT_USE = 0.5;

// Short function words say nothing about a fact, so a fact with no long words is matched on the rest.
const FUNCTION_WORDS = new Set(
	'a an and are as at be but by for from had has have he her his in is it its of on or she that the their they this to was were who with'.split(
		' '
	)
);

// Life-date words restate the stone's dates, so a quote made of them adds nothing (FR-013).
const LIFE_MARKERS = new Set(
	'born birth died death passed away deceased aged age year years old'.split(' ')
);
const ORDINAL = /^\d+(?:st|nd|rd|th)$/;

// A quote that names survivors would put living people's names into the story (FR-017).
const SURVIVORS =
	/\b(survived by|survivors?|leaves behind|leaving behind|left to mourn|she leaves|he leaves)\b/i;

// A relative named in a quote is usually a survivor, so the quote is dropped unless it says the
// relative died first. Matched on the original text: a name is a capitalized word.
const RELATIVE_WORDS =
	'husband wife spouse partner son sons daughter daughters brother brothers sister sisters mother father grandson granddaughter grandchildren nephew niece stepson stepdaughter'.split(
		' '
	);
// Each letter-case spelling is listed, because a case-insensitive flag would also let \p{Lu} match lowercase.
/**
 * Builds a regex alternation of each word in lower, capitalized and upper case.
 * @param words Lowercase words.
 * @returns The alternation source, without a group.
 */
const spellings = (words: string[]): string =>
	words.flatMap((w) => [w, w[0].toUpperCase() + w.slice(1), w.toUpperCase()]).join('|');
const RELATIVE = spellings(RELATIVE_WORDS);
const POSSESSIVE = spellings(['her', 'his', 'their']);
// A name is a capital followed by letters in any case, so JOHN and John both count.
const NAME = String.raw`\p{Lu}[\p{L}'’-]+`;
const NAMED_RELATIVE = new RegExp(
	String.raw`\b(?:${RELATIVE})\b[^.;]{0,12}?${NAME}|${NAME},?\s+(?:${POSSESSIVE})\s+(?:${RELATIVE})\b`,
	'u'
);
const NAMED_RELATIVE_CASE = /\p{Lu}/u;
const MONTH_WORD = new RegExp(String.raw`\b(?:${[...MONTHS].join('|')})\b`, 'giu');
const PREDECEASED = /\b(predeceased|preceded (?:her |him |them )?in death)\b/i;

/** A fact whose quote was found verbatim in a cited source. */
export type VerifiedFact = RawFact;

/** A records-based story, or `insufficient` when the records hold nothing beyond the stone. */
type Grounded = Omit<Extract<Story, { status: 'told' }>, 'voice'> | { status: 'insufficient' };

/**
 * Lowercases and collapses everything except letters and digits to single spaces.
 * @param s Text to normalize.
 * @returns Normalized text.
 */
