import { sveltekit } from '@sveltejs/kit/vite';

export default defineConfig({
	plugins: [
		sveltekit({
			compilerOptions: {
				// Runes everywhere except dependencies, which may still ship legacy components.
				runes: ({ filename }) =>
					filename.split(/[/\\]/).includes('node_modules') ? undefined : true
			},
			adapter: adapter()
		})
	],
	test: {
		expect: { requireAssertions: true },
		include: ['src/**/*.{test,spec}.ts', 'scripts/**/*.{test,spec}.ts'],
		environment: 'node',
		coverage: {
			provider: 'v8',
			reporter: ['text', 'lcov'],
			include: ['src/**/*.ts', 'scripts/**/*.ts'],
			// Tests, Playwright specs, ambient types and SvelteKit's env declaration hold no app logic.
			exclude: ['**/*.test.ts', '**/*.spec.ts', '**/*.e2e.ts', 'src/app.d.ts', 'src/env.ts']
		}
	}
});

