s=s.replace("fetchPage: async (url: string) => cases.find((c) => url in c.pages)?.pages[url] ?? null","fetchPage: async (url: string) =>\n\t\t[...sets.written, ...sets.recorded].find((c) => url in c.pages)?.pages[url] ?? null")
