	// A maiden-name OR variant pulled in unrelated hits and buried the real record in live searches.
	// A quoted nickname would break the exact-name quoting; the matcher still uses it.
	const name = inscription.name
		.replace(/["“”][^"“”]*["“”]/g, ' ')
		.replace(/\s+/g, ' ')
		.trim();
	// Unquoted, so an obituary naming the town in other words still ranks. Lowercase, so a carved
	// "OR" can't act as a search operator.
	const place = inscription.place
		?.toLowerCase()
		.replace(/[^\p{L}\p{N}' -]+/gu, ' ')
		.replace(/\s+/g, ' ')
		.trim();
		?.replace(/[^\p{L}\p{N}' -]+/gu, ' ')
		.replace(/\s+/g, ' ')
		.trim();
	return [`"${name}"`, ...years, place, '(obituary OR grave OR cemetery)']
		.filter(Boolean)
		.join(' ');
}
