4	/**
5	 * Asks the browser where the visitor stands, which is usually the cemetery.
6	 * @returns Latitude and longitude, or null when denied, unavailable or too slow.
7	 */
8	export function locate(): Promise<{ lat: number; lon: number } | null> {
9		if (!('geolocation' in navigator)) return Promise.resolve(null);
10		return new Promise((resolve) => {
11			const timer = setTimeout(() => resolve(null), PATIENCE_MS);
12			/**
13			 * Settles the lookup once.
14			 * @param at The position, or null.
15			 */
16			const done = (at: { lat: number; lon: number } | null) => {
17				clearTimeout(timer);
18				resolve(at);
19			};
20			navigator.geolocation.getCurrentPosition(
21				(p) => done({ lat: p.coords.latitude, lon: p.coords.longitude }),
22				() => done(null),
23				// A town is all the search needs, so a coarse or ten-minute-old fix will do.
24				{ enableHighAccuracy: false, maximumAge: 600_000, timeout: PATIENCE_MS }
25			);
26		});
27	}
