22	/**
23	 * Waits for this process's next one-per-second slot.
24	 */
25	async function throttle(): Promise<void> {
26		const now = Date.now();
27		const at = Math.max(now, nextSlot);
28		nextSlot = at + MIN_GAP_MS;
29		if (at > now) await new Promise((resolve) => setTimeout(resolve, at - now));
