32	/**
33	 * Names the town and state or country at a point, for narrowing search.
34	 * @param at Where the photo was taken or the visitor stands.
35	 * @returns For example "Eugene, Oregon", or null when the lookup fails or finds no place.
36	 */
37	export async function placeAt(at: Coordinates): Promise<string | null> {
38		// Two decimals is about a kilometre: enough for the town, without sending the visitor's spot.
39		const params = new URLSearchParams({
40			format: 'jsonv2',
41			lat: at.lat.toFixed(2),
42			lon: at.lon.toFixed(2),
43			zoom: '10',
44			addressdetails: '1'
45		});
46		await throttle();
47		try {
48			const res = await fetch(`${ENDPOINT}?${params}`, {
49				headers: { 'user-agent': USER_AGENT, 'accept-language': 'en' },
50				signal: AbortSignal.timeout(TIMEOUT_MS)
51			});
52			if (!res.ok) return null;
53			const { address } = (await res.json()) as { address?: Address };
54			const local =
