			}
		}
		const merged = [...seen.values()];
		const records = dropGated(
			merged.map((m) => ({
				id: m.id,
				url: m.hit.link,
				title: m.hit.title,
				site: new URL(m.hit.link).hostname,
				snippet: m.hit.snippet
