			born: c.born,
			died: c.died,
			sources: c.sources.map((s) => ({
				url: s.url,
				title: s.title,
				snippet: s.snippet,
				engines: seen.get(canonicalUrl(s.url)!)?.engines ?? []
			}))
		}));
		const row = {
			file,
			person,
			query,
			searchMs,
			engines: runs.map((r) => r.run),
			mergedResults: merged.length,
			afterGatedFilter: records.length,
			candidates
		};
